    "standardFlowEnabled": true, "directAccessGrantsEnabled": false,
    "redirectUris": ["https://app.example.med/auth/keycloak/callback", "https://app.example.med/auth/keycloak/link/callback"],
    "webOrigins": ["https://app.example.med"],
